import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"战技 & 被动","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills-abilities.md","filePath":"guide/skills-abilities.md","lastUpdated":1786201985000}'),o={name:"guide/skills-abilities.md"};function s(i,t,l,n,h,b){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="战技-被动" tabindex="-1">战技 &amp; 被动 <a class="header-anchor" href="#战技-被动" aria-label="Permalink to &quot;战技 &amp; 被动&quot;">​</a></h1><h2 id="主动战技" tabindex="-1">主动战技 <a class="header-anchor" href="#主动战技" aria-label="Permalink to &quot;主动战技&quot;">​</a></h2><p>简称<strong>战技</strong>。释放战技会消耗<strong>爆发能量</strong>。</p><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>初始状态</td><td>无，需通过学习解锁</td></tr><tr><td>学习后等级</td><td>1 级</td></tr><tr><td>最高等级</td><td>6 级</td></tr><tr><td>升级所需等级</td><td>12/24/36/48/60</td></tr><tr><td>吟唱</td><td>❌ 不需要，可以直接发动技能效果</td></tr></tbody></table><h2 id="被动战技" tabindex="-1">被动战技 <a class="header-anchor" href="#被动战技" aria-label="Permalink to &quot;被动战技&quot;">​</a></h2><p>简称<strong>被动</strong>。被动会<strong>随时判断</strong>其所需条件是否成立，并使效果生效。</p><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>初始状态</td><td>可能需要通过学习解锁</td></tr><tr><td>学习后等级</td><td>1 级</td></tr><tr><td>升级</td><td>通常被动技能没有升级选项</td></tr><tr><td>触发方式</td><td>随时判断条件是否成立并生效</td></tr></tbody></table><h2 id="战斗天赋" tabindex="-1">战斗天赋 <a class="header-anchor" href="#战斗天赋" aria-label="Permalink to &quot;战斗天赋&quot;">​</a></h2><p>根据角色的定位（核心、先锋、近卫、支援、治疗），角色可以学习得到与之定位相应的<strong>战斗天赋</strong>。这些战斗天赋<strong>属于被动战技</strong>。</p><table tabindex="0"><thead><tr><th>定位</th><th>可获得对应天赋</th></tr></thead><tbody><tr><td>核心 / 先锋 / 近卫 / 支援 / 治疗</td><td>各自定位的战斗天赋</td></tr></tbody></table><ul><li>当角色具有<strong>多个定位</strong>时，允许角色学习多个战斗天赋</li><li>但只能选择其中 <strong>1 个</strong>战斗天赋生效</li></ul>',11)])])}const g=a(o,[["render",s]]);export{_ as __pageData,g as default};
